// Private authored assessment content. Difficulty describes slots within a level;
// these programs have not been empirically calibrated on candidates.
// Numerical variants change scenario inputs and exercise a numerical result or
// invariant. Decision variants change the constraint and appropriate intervention.
const numeric = (question, solve, unit = '') => ({ question, solve, unit });
const decision = (cases, options) => ({ cases, options });
const topic = (name, skills, first, second) => ({ name, skills, tasks: [first, second] });

function variants(id, task, skills) {
  if (task.cases) return task.cases.map((text, correct) => ({
    id: `${id}-${correct + 1}`, text, options: [...task.options], correct, skills: [...skills],
  }));
  return [2, 3, 4, 5].map((value, index) => {
    const answer = task.solve(value);
    if (!Number.isFinite(answer) || answer < 0 || !Number.isInteger(answer)) throw new Error(`Invalid authored answer: ${id}`);
    const wrong = [...new Set([answer + 1, answer - 1, answer * 2, answer + 2, answer + 3])]
      .filter(item => item >= 0 && item !== answer).slice(0, 3);
    const choices = [...wrong];
    const correct = index % 4;
    choices.splice(correct, 0, answer);
    return { id: `${id}-${index + 1}`, text: task.question(value),
      options: choices.map(item => `${item}${task.unit ? ` ${task.unit}` : ''}`), correct, skills: [...skills] };
  });
}

function program(specialization, grade, modules) {
  return { topics: modules.map(module => module.name), families: modules.flatMap((module, index) => module.tasks.map((task, slot) => {
    const id = `englevel-${specialization.toLowerCase()}-${grade.toLowerCase()}-${index + 1}-${slot + 1}`;
    return { id, topic: module.name, difficulty: slot + 1, skills: [...module.skills], variants: variants(id, task, module.skills) };
  })) };
}

